effect.shader:
const float PI = 3.14159265;
void main() {
    float a = angle * PI / 180.0;
    vec2 d = vec2(cos(a), sin(a)) * amount;
    d.x /= max(acAspect, 1e-4);
    float r = texture(inputImg, acScreenNorm + d).r;
    float g = texture(inputImg, acScreenNorm).g;
    float b = texture(inputImg, acScreenNorm - d).b;
    float al = texture(inputImg, acScreenNorm).a;
    fragColor = vec4(r, g, b, al);
}
